<template>
  <div class="page-grid control-page">
    <a-card class="section-card"><div class="toolbar"><div><a-typography-title :level="4" style="margin:0">调度控制</a-typography-title><a-typography-text type="secondary">控制申请、审批、执行与偏差闭环</a-typography-text></div><a-space><a-select v-model:value="filter" :options="filters" aria-label="控制状态"/><a-button :loading="loading" aria-label="刷新控制命令" @click="load">刷新</a-button></a-space></div></a-card>
    <a-card class="section-card" title="控制命令"><a-alert v-if="error" type="error" :message="error" show-icon style="margin-bottom:16px"/><a-table :columns="columns" :data-source="filtered" :loading="loading" row-key="id" :pagination="false"><template #bodyCell="{ column, record }"><template v-if="column.key === 'status'"><a-tag :color="statusColor(record.status)">{{ statusText(record.status) }}</a-tag></template><template v-else-if="column.key === 'validity'">{{ formatTime(record.valid_from) }} - {{ formatTime(record.valid_until) }}</template><template v-else-if="column.key === 'approval'">{{ record.required_approvals }} 人</template><template v-else-if="column.key === 'action'"><a-space v-if="canApprove && record.status === 'pending_approval'"><a-button size="small" type="primary" @click="run(record, 'approve')">批准</a-button><a-button size="small" danger @click="run(record, 'reject')">拒绝</a-button></a-space><a-button v-else-if="canExecute && record.status === 'approved'" size="small" type="primary" @click="run(record, 'execute')">执行</a-button><a-button v-else-if="canExecute && ['failed','unknown','deviation','rollback_pending'].includes(record.status)" size="small" danger @click="run(record, 'rollback')">回滚</a-button></template></template><template #emptyText><a-empty description="暂无控制命令" /></template></a-table></a-card>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { ApiError } from '@/api/client';
import { controlApi, type ControlCommand } from '@/api/control';
import { usePermissionStore } from '@/stores/permission';
const permission = usePermissionStore(); const commands = ref<ControlCommand[]>([]); const loading = ref(false); const error = ref(''); const filter = ref('all');
const filters = [{ label: '全部', value: 'all' }, { label: '待审批', value: 'pending_approval' }, { label: '已批准', value: 'approved' }, { label: '执行中', value: 'executing' }, { label: '异常', value: 'deviation' }];
const columns = [{ title: '命令', dataIndex: 'id', key: 'id' }, { title: '目标', dataIndex: ['target', 'asset_type'], key: 'target' }, { title: '审批', key: 'approval' }, { title: '有效期', key: 'validity' }, { title: '状态', key: 'status' }, { title: '操作', key: 'action' }];
const filtered = computed(() => filter.value === 'all' ? commands.value : commands.value.filter(item => item.status === filter.value)); const canApprove = computed(() => permission.hasPermission('control.approve')); const canExecute = computed(() => permission.hasPermission('control.execute'));
const statusText = (value: string) => ({ pending_approval: '待审批', approved: '已批准', executing: '执行中', succeeded: '已完成', failed: '失败', unknown: '未知', deviation: '偏差', rollback_pending: '待回滚', rolled_back: '已回滚', rejected: '已拒绝', expired: '已过期' }[value] || value); const statusColor = (value: string) => ['failed','unknown','deviation'].includes(value) ? 'red' : value === 'succeeded' ? 'green' : 'blue'; const formatTime = (value: string) => new Date(value).toLocaleString('zh-CN');
async function load() { loading.value = true; error.value = ''; try { commands.value = await controlApi.listCommands(); } catch (e) { error.value = e instanceof ApiError || e instanceof Error ? e.message : '加载控制命令失败'; } finally { loading.value = false; } }
async function run(command: ControlCommand, action: string) { try { if (action === 'approve') await controlApi.approve(command.id); else if (action === 'reject') await controlApi.reject(command.id); else if (action === 'execute') await controlApi.execute(command.id, crypto.randomUUID()); else await controlApi.rollback(command.id, crypto.randomUUID()); await load(); } catch (e) { error.value = e instanceof Error ? e.message : '控制操作失败'; } }
onMounted(load);
</script>
<style scoped>.control-page{min-width:0}.section-card :deep(.ant-table-cell){vertical-align:middle}@media(max-width:760px){.control-page :deep(.toolbar){align-items:flex-start;flex-direction:column}.control-page :deep(.ant-table){min-width:820px}}</style>
